input.content:
/*
 * Focused regression test for the upstream fix
 *   "malloc-fail: Fix memory leak in xmlStaticCopyNodeList" (a22bd982, #344)
 *
 * The test installs a custom allocator through xmlMemSetup() that can be told
 * to fail a single allocation by index.  It then copies a three-node list via
 * the public xmlCopyNodeList() (which calls the internal
 * xmlStaticCopyNodeList) once per possible failure index.
 *
 * Metric:
 *   max_leak = maximum number of net live allocations left behind after the
 *              copy attempt and the (optional) free of the returned list.
 *
 * Unpatched target: copying node 2 fails after node 1 was copied, the partial
 * list is leaked  -> max_leak > 0.
 * Patched target:   the partial list is freed via xmlFreeNodeList(ret)
 *                   -> max_leak == 0.
 *
 * Exit code 0 only when max_leak == 0, positive path copies 3 nodes, and the
 * source list is untouched.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libxml/tree.h>
#include <libxml/xmlmemory.h>
#include <libxml/parser.h>

static size_t live = 0;
static long alloc_calls = 0;
static long fail_at = -1;

static void *t_malloc(size_t size) {
    if (fail_at >= 0 && alloc_calls == fail_at) {
        alloc_calls++;
        return NULL;
    }
    alloc_calls++;
    void *p = malloc(size ? size : 1);
    if (p != NULL)
        live++;
    return p;
}

static void t_free(void *p) {
    if (p != NULL) {
        free(p);
        live--;
    }
}

static void *t_realloc(void *p, size_t size) {
    if (fail_at >= 0 && alloc_calls == fail_at) {
        alloc_calls++;
        return NULL;
    }
    alloc_calls++;
    if (p == NULL) {
        void *q = malloc(size ? size : 1);
        if (q != NULL)
            live++;
        return q;
    }
    return realloc(p, size);
}

static char *t_strdup(const char *s) {
    size_t n = strlen(s) + 1;
    char *p = (char *) t_malloc(n);
    if (p != NULL)
        memcpy(p, s, n);
    return p;
}

static void silent_error(void *ctx, const char *msg, ...) {
    (void) ctx;
    (void) msg;
}

int main(void) {
    xmlNodePtr a, b, c, copy;
    size_t base;
    long f, max_leak = 0, leak_at = -1;
    int positive_ok = 0;
    int copy_success = 0;

    if (xmlMemSetup(t_free, t_malloc, t_realloc, t_strdup) != 0) {
        printf("RESULT setup=failed\n");
        return 2;
    }
    xmlSetGenericErrorFunc(NULL, silent_error);
    xmlInitParser();

    a = xmlNewNode(NULL, BAD_CAST "a");
    b = xmlNewNode(NULL, BAD_CAST "b");
    c = xmlNewNode(NULL, BAD_CAST "c");
    if (a == NULL || b == NULL || c == NULL) {
        printf("RESULT setup=list_failed\n");
        return 2;
    }
    a->next = b;
    b->prev = a;
    b->next = c;
    c->prev = b;

    base = live;

    for (f = 0; f < 200; f++) {
        long delta;

        fail_at = -1;
        alloc_calls = 0;
        fail_at = f;
        copy = xmlCopyNodeList(a);
        fail_at = -1;

        if (copy != NULL) {
            xmlFreeNodeList(copy);
            copy_success = 1;
        }
        delta = (long) live - (long) base;
        if (delta > max_leak) {
            max_leak = delta;
            leak_at = f;
        }
    }

    /* Positive path: no injected failure. */
    fail_at = -1;
    copy = xmlCopyNodeList(a);
    if (copy != NULL) {
        int count = 0;
        xmlNodePtr it;
        for (it = copy; it != NULL; it = it->next)
            count++;
        positive_ok = (count == 3);
        xmlFreeNodeList(copy);
    }

    printf("RESULT max_leak=%ld leak_at=%ld positive_ok=%d copy_success=%d base=%zu final=%zu\n",
           max_leak, leak_at, positive_ok, copy_success, base, live);

    /* The source list must not have been modified or freed. */
    if (a->next != b || b->prev != a || b->next != c || c->prev != b) {
        printf("RESULT source_list_corrupted=1\n");
        return 3;
    }

    a->next = NULL;
    b->next = NULL;
    c->next = NULL;
    xmlFreeNode(a);
    xmlFreeNode(b);
    xmlFreeNode(c);
    xmlCleanupParser();

    return (max_leak == 0 && positive_ok == 1 && copy_success) ? 0 : 1;
}

